import{z as d,x as o,o as t,c as A,q as E,j as l,D as e,d as i,s,S as n}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"杠杆与波动拖累","description":"","frontmatter":{"title":"杠杆与波动拖累","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/leverage-volatility-drag.md","filePath":"quant/leverage-volatility-drag.md","lastUpdated":1791413859000}'),B={name:"quant/leverage-volatility-drag.md"};function m(p,a,h,_,C,D){const r=o("Mermaid");return t(),A("div",null,[a[2]||(a[2]=E('<h1 id="杠杆与波动拖累" tabindex="-1">杠杆与波动拖累 <a class="header-anchor" href="#杠杆与波动拖累" aria-label="Permalink to &quot;杠杆与波动拖累&quot;">​</a></h1><div class="epigraph"><p>每日再平衡的杠杆 ETF 的复利，不等于标的复利乘杠杆倍数；方差项把路径拉向几何均值。</p><footer>—— 对照 Cheng and Madhavan 对杠杆 ETF 路径依赖的分析；波动拖累见连续时间财富 $r-\\tfrac12\\sigma^2$ 项</footer></div><p><a href="/quant/target-date-glidepath">上一课</a>的路径默认未杠杆化。本课缺口是 <strong>\\(2\\times\\)、\\(3\\times\\) 与融资杠杆的离散再平衡</strong>：算术收益可以是 \\(\\lambda\\) 倍，几何收益少一块 \\(\\tfrac12\\lambda(\\lambda-1)\\sigma^2\\) 量级的拖累。主干 Kelly 已有杠杆上限；这里写清楚拖累与再平衡溢价的符号关系，后课专门写再平衡溢价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设标的日收益 \\(r_t\\)，杠杆 ETF 近 \\(\\lambda r_t\\) 再扣费。多日财富 \\(\\prod(1+\\lambda r_t)\\)，不是 \\((1+\\lambda\\bar r)^T\\)。对数近似 \\(\\lambda\\mu-\\tfrac12\\lambda^2\\sigma^2\\) 对对数效用投资者，而标的是 \\(\\mu-\\tfrac12\\sigma^2\\)。杠杆既放大漂移也放大方差项。震荡市里标的来回、杠杆产品因每日重置而锁亏——这是凸性/再平衡，不是「产品骗人」。问题是把拖累写成预期项，放进 Merton 实现，而不是在回测里用算术 \\(\\lambda\\bar r\\) 当持有期收益。</p><p><span class="marginnote">术语翻译：波动拖累（volatility drag）就是「来回坐过山车掉的钱」——涨 10% 再跌 10%，算术平均是 0，但 \\(1.1\\times 0.9=0.99\\)，本金少了 1%。方差越大、来回越频繁，损耗越大；杠杆把方差放大 \\(\\lambda^2\\) 倍，拖累也近似按 \\(\\lambda^2\\) 增长。</span></p>',6)),(t(),l(n,null,{default:e(()=>[s(r,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20D1%5B%22%E7%AC%AC%201%20%E5%A4%A9%EF%BC%9A%E6%A0%87%E7%9A%84%E8%B7%8C%2010%25%22%5D%20--%3E%20P1%5B%222%20%E5%80%8D%20ETF%EF%BC%9A%E8%B7%8C%2020%25%EF%BC%8C%E5%87%80%E5%80%BC%200.80%22%5D%0A%20%20P1%20--%3E%20R%5B%22%E6%AF%8F%E6%97%A5%E9%87%8D%E7%BD%AE%EF%BC%9A%E6%9A%B4%E9%9C%B2%E9%87%8D%E6%96%B0%E5%8A%A0%E5%9B%9E%202%20%E5%80%8D%22%5D%0A%20%20R%20--%3E%20D2%5B%22%E7%AC%AC%202%20%E5%A4%A9%EF%BC%9A%E6%A0%87%E7%9A%84%E6%B6%A8%2010%25%EF%BC%8C%E5%9B%9E%E5%88%B0%E5%8E%9F%E7%82%B9%22%5D%0A%20%20D2%20--%3E%20P2%5B%222%20%E5%80%8D%20ETF%EF%BC%9A%E6%B6%A8%2020%25%EF%BC%8C%E5%87%80%E5%80%BC%200.96%22%5D%0A%20%20P2%20--%3E%20L%5B%22%E6%A0%87%E7%9A%84%E6%89%93%E5%B9%B3%E3%80%81ETF%20%E4%BA%8F%204%25%EF%BC%9A%E8%BF%99%E5%B0%B1%E6%98%AF%E6%B3%A2%E5%8A%A8%E6%8B%96%E7%B4%AF%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p>融资杠杆（借钱买股票、不每日精确重置）的拖累形式不同：利息是现金，再平衡不是强制每日。不要把杠杆 ETF 的路径公式套到经纪商保证金账户上。</p><h3 id="拖累不是费用的别名" tabindex="-1">拖累不是费用的别名 <a class="header-anchor" href="#拖累不是费用的别名" aria-label="Permalink to &quot;拖累不是费用的别名&quot;">​</a></h3><p>管理费与融资利率是另一项。波动拖累在零费用下仍在。高 \\(\\sigma\\)、高 \\(\\lambda\\)、长持有、震荡（负自相关）时拖累大；趋势市（正自相关）里每日再平衡可以获利，即后课再平衡溢价的反面或同面，取决于你站在产品哪一侧。</p><p><span class="marginnote">波动瞄准策略每日调杠杆，也有同类路径项。把它当免费的「稳夏普」，忽略了调仓冲击与拖累。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>报告持有期收益用产品 NAV 路径，不用 \\(\\lambda\\times\\) 指数收益。预测：用预期 \\(\\sigma\\)（HAR）估拖累，持有期超过数日的杠杆 ETF 必须有这项。对冲：用期货加现金复制杠杆暴露，控制再平衡频率，使拖累成为选择而不是产品强制。Merton：\\(\\lambda\\) 进 \\(\\pi\\)，但效用按几何，自动惩罚过高 \\(\\lambda\\)。</p><p><span class="marginnote">数字实例：标的年化 \\(\\mu=8\\%\\)、\\(\\sigma=20\\%\\)，几何收益约 \\(8\\%-0.5\\times 4\\%=6\\%\\)；2 倍杠杆近似为 \\(16\\%-0.5\\times 4\\times 4\\%=8\\%\\)——不是 \\(16\\%\\)。杠杆翻倍只把几何收益多挤出 2 个百分点，方差项吃掉了另一半，这正是 Merton 框架自动惩罚高杠杆的原因。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每日重置把暴露钉在 \\(\\lambda\\)，等价于持续买卖：涨则加仓、跌则减仓（对多头杠杆）。震荡时买高卖低。这与固定份额组合的再平衡相反或相同，取决于比较对象。连续时间 Itô 的 \\(-\\tfrac12\\sigma^2\\) 是同一数学。</p>',9)),(t(),l(n,null,{default:e(()=>[s(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Daily%5B%22%E6%AF%8F%E6%97%A5%E9%87%8D%E7%BD%AE%E6%9A%B4%E9%9C%B2%E5%88%B0%20%CE%BB%22%5D%20--%3E%20Path%5B%22%E2%88%8F%201%20%E5%8A%A0%20%CE%BB%20r%22%5D%0A%20%20Path%20--%3E%20Drag%5B%22%E5%87%A0%E4%BD%95%E5%B0%8F%E4%BA%8E%20%CE%BB%20%E5%80%8D%E7%AE%97%E6%9C%AF%22%5D%0A%20%20Vol%5B%22%CF%83%20%E4%B8%8E%20%CE%BB%22%5D%20--%3E%20Drag%0A%20%20Trend%5B%22%E8%B6%8B%E5%8A%BF%E5%AF%B9%E9%9C%87%E8%8D%A1%22%5D%20--%3E%20Sign%5B%22%E6%8B%96%E7%B4%AF%E6%88%96%E5%86%8D%E5%B9%B3%E8%A1%A1%E5%A2%9E%E7%9B%8A%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>隔夜跳、跟踪误差、对手方（ETN）不是拖累公式能覆盖的。反向杠杆在趋势下跌中可赢，但仍有方差项。本课不建议用杠杆 ETF 当长期 TDF 核心。监管与适当性另论。</p><p><span class="marginnote">常见误区：把杠杆 ETF 的拖累公式套到融资账户上。借钱买股票不强制每日重置，路径项的形式不同，还有利息现金流；也别用「指数 10 年涨了 100%，3 倍产品就该涨 300%」做长持决策——只有连续单边趋势才接近倍数，震荡年积累的拖累会显著偏离。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>每日杠杆的复利不是 \\(\\lambda\\) 倍标的复利；方差项是一等公民。</li><li>融资杠杆与杠杆 ETF 的重置规则不同，公式不可混用。</li><li>震荡锁亏、趋势可能增益，接到再平衡溢价。</li><li>出处：Cheng and Madhavan 对杠杆 ETF 的分析；Itô 公式的几何均值项。</li></ul>',5))])}const g=d(B,[["render",m]]);export{T as __pageData,g as default};
